import { useEffect, useRef } from "react";

interface IGiscusCommentsProps {
  term?: string;
  category?: string;
}

export default function GiscusComments({ term = "Blog Comments", category = "Announcements" }: IGiscusCommentsProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const script = document.createElement("script");
    script.src = "https://giscus.app/client.js";
    script.setAttribute("data-repo", "YangRonglin/biohacker.fun");
    script.setAttribute("data-repo-id", "");
    script.setAttribute("data-category", category);
    script.setAttribute("data-category-id", "");
    script.setAttribute("data-mapping", "title");
    script.setAttribute("data-strict", "0");
    script.setAttribute("data-reactions-enabled", "1");
    script.setAttribute("data-emit-metadata", "0");
    script.setAttribute("data-input-position", "bottom");
    script.setAttribute("data-theme", "dark");
    script.setAttribute("data-lang", "en");
    script.setAttribute("crossorigin", "anonymous");
    script.async = true;

    container.appendChild(script);

    return () => {
      container.innerHTML = "";
    };
  }, [term, category]);

  return (
    <div className="mt-12 pt-8 border-t border-[#1E1E1E]">
      <h3 className="text-xl font-bold text-[#00FF88] mb-6 font-space">
        <span className="text-[#FF3366] mr-2">//</span>
        Comments
      </h3>
      <div
        ref={containerRef}
        className="rounded-lg border border-[#1E1E1E] bg-[#141414] p-4 min-h-[200px]"
      />
    </div>
  );
}
