import React from "react";
import ReactECharts from "echarts-for-react";
import { motion } from "framer-motion";
import { HeartIcon, MoonIcon, ActivityIcon, AppleIcon, TrendingUpIcon, ZapIcon } from "lucide-react";

const neonGreen = "#00FF88";
const neonPurple = "#7B2DFF";
const neonRed = "#FF3366";
const darkBg = "#0D0D0D";
const cardBg = "#141414";
const borderColor = "#1E1E1E";
const textPrimary = "#E8E8E8";
const textMuted = "#888888";

interface IMetricCardProps {
  icon: React.ReactNode;
  label: string;
  value: string;
  unit: string;
  trend?: string;
  trendUp?: boolean;
}

const MetricCard: React.FC<IMetricCardProps> = ({ icon, label, value, unit, trend, trendUp }) => (
  <motion.div
    initial={{ opacity: 0, y: 20 }}
    animate={{ opacity: 1, y: 0 }}
    className="rounded-lg border border-[#1E1E1E] bg-[#141414] p-4 hover:border-[#00FF88]/50 hover:shadow-[0_0_15px_rgba(0,255,136,0.15)] transition-all duration-300"
  >
    <div className="flex items-center justify-between mb-2">
      <div className="flex items-center gap-2 text-[#888888]">
        {icon}
        <span className="text-xs font-mono uppercase tracking-wider">{label}</span>
      </div>
      {trend && (
        <span className={`text-xs font-mono ${trendUp ? "text-[#00FF88]" : "text-[#FF3366]"}`}>
          {trend}
        </span>
      )}
    </div>
    <div className="flex items-baseline gap-1">
      <span className="text-2xl font-bold text-[#E8E8E8] font-['Space_Grotesk']">{value}</span>
      <span className="text-sm text-[#888888] font-mono">{unit}</span>
    </div>
  </motion.div>
);

interface IChartPanelProps {
  title: string;
  icon: React.ReactNode;
  children: React.ReactNode;
  className?: string;
}

const ChartPanel: React.FC<IChartPanelProps> = ({ title, icon, children, className = "" }) => (
  <motion.div
    initial={{ opacity: 0, y: 20 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ delay: 0.1 }}
    className={`rounded-lg border border-[#1E1E1E] bg-[#141414] p-4 hover:border-[#00FF88]/30 transition-all duration-300 ${className}`}
  >
    <div className="flex items-center gap-2 mb-4">
      <span className="text-[#00FF88]">{icon}</span>
      <h3 className="text-sm font-bold text-[#E8E8E8] font-['Space_Grotesk'] uppercase tracking-wider">{title}</h3>
    </div>
    {children}
  </motion.div>
);

