import { motion } from "framer-motion";

interface ICircuitDecorationProps {
  className?: string;
  variant?: "hero" | "section";
}

export default function CircuitDecoration({ className = "", variant = "hero" }: ICircuitDecorationProps) {
  const strokeGreen = "#00FF88";
  const strokePurple = "#7B2DFF";
  const strokeDim = "#1E1E1E";

  if (variant === "section") {
    return (
      <svg
        className={`pointer-events-none absolute inset-0 h-full w-full ${className}`}
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 1200 200"
        preserveAspectRatio="none"
      >
        <defs>
          <filter id="glow-section">
            <feGaussianBlur stdDeviation="2" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        <motion.path
          d="M0,100 L120,100 L140,80 L200,80 L220,100 L350,100 L370,120 L500,120 L520,100 L650,100 L670,80 L800,80 L820,100 L950,100 L970,120 L1200,120"
          fill="none"
          stroke={strokeGreen}
          strokeWidth="1"
          opacity="0.3"
          filter="url(#glow-section)"
          initial={{ pathLength: 0, opacity: 0 }}
          animate={{ pathLength: 1, opacity: 0.3 }}
          transition={{ duration: 2, ease: "easeInOut" }}
        />
        <motion.circle cx="140" cy="80" r="3" fill={strokeGreen} opacity="0.6" filter="url(#glow-section)" initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ delay: 0.5, duration: 0.3 }} />
        <motion.circle cx="370" cy="120" r="3" fill={strokeGreen} opacity="0.6" filter="url(#glow-section)" initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ delay: 0.8, duration: 0.3 }} />
        <motion.circle cx="670" cy="80" r="3" fill={strokeGreen} opacity="0.6" filter="url(#glow-section)" initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ delay: 1.1, duration: 0.3 }} />
        <motion.circle cx="970" cy="120" r="3" fill={strokeGreen} opacity="0.6" filter="url(#glow-section)" initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ delay: 1.4, duration: 0.3 }} />
      </svg>
    );
  }

  return (
    <svg
      className={`pointer-events-none absolute inset-0 h-full w-full ${className}`}
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 1440 900"
      preserveAspectRatio="xMidYMid slice"
    >
      <defs>
        <filter id="glow-green">
          <feGaussianBlur stdDeviation="3" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
        <filter id="glow-purple">
          <feGaussianBlur stdDeviation="3" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
        <linearGradient id="dna-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor={strokeGreen} />
          <stop offset="50%" stopColor={strokePurple} />
          <stop offset="100%" stopColor={strokeGreen} />
        </linearGradient>
        <pattern id="scanlines" width="4" height="4" patternUnits="userSpaceOnUse">
          <rect width="4" height="2" fill="rgba(0,255,136,0.02)" />
        </pattern>
      </defs>

      <rect width="100%" height="100%" fill="url(#scanlines)" />

      {/* DNA Helix - Left Strand */}
      <motion.path
        d="M200,0 C280,100 280,200 200,300 C120,400 120,500 200,600 C280,700 280,800 200,900"
        fill="none"
        stroke={strokeGreen}
        strokeWidth="2"
        opacity="0.4"
        filter="url(#glow-green)"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 3, ease: "easeInOut" }}
      />

      {/* DNA Helix - Right Strand */}
      <motion.path
        d="M320,0 C240,100 240,200 320,300 C400,400 400,500 320,600 C240,700 240,800 320,900"
        fill="none"
        stroke={strokePurple}
        strokeWidth="2"
        opacity="0.4"
        filter="url(#glow-purple)"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 3, ease: "easeInOut", delay: 0.3 }}
      />

      {/* DNA Rungs */}
      {[100, 200, 300, 400, 500, 600, 700, 800].map((y, i) => (
        <motion.line
          key={`rung-${i}`}
          x1={200 + Math.sin((y / 300) * Math.PI) * 60}
          y1={y}
          x2={320 - Math.sin((y / 300) * Math.PI) * 60}
          y2={y}
          stroke={strokeGreen}
          strokeWidth="1"
          opacity="0.2"
          initial={{ scaleX: 0 }}
          animate={{ scaleX: 1 }}
          transition={{ delay: 1 + i * 0.15, duration: 0.4 }}
        />
      ))}

      {/* Circuit Board Lines - Top Right */}
      <motion.path
        d="M1200,50 L1100,50 L1080,70 L1000,70 L980,50 L900,50 L880,70 L800,70"
        fill="none"
        stroke={strokeGreen}
        strokeWidth="1.5"
        opacity="0.25"
        filter="url(#glow-green)"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 2, delay: 0.5 }}
      />
      <motion.path
        d="M1200,120 L1120,120 L1100,140 L1020,140 L1000,120 L920,120 L900,140 L820,140"
        fill="none"
        stroke={strokePurple}
        strokeWidth="1"
        opacity="0.2"
        filter="url(#glow-purple)"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 2, delay: 0.8 }}
      />

      {/* Circuit Board Lines - Bottom Left */}
      <motion.path
        d="M50,850 L150,850 L170,830 L250,830 L270,850 L350,850 L370,830 L450,830"
        fill="none"
        stroke={strokeGreen}
        strokeWidth="1.5"
        opacity="0.25"
        filter="url(#glow-green)"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 2, delay: 1 }}
      />

      {/* Circuit Board Lines - Bottom Right */}
      <motion.path
        d="M1400,800 L1300,800 L1280,780 L1200,780 L1180,800 L1100,800 L1080,780 L1000,780"
        fill="none"
        stroke={strokePurple}
        strokeWidth="1"
        opacity="0.2"
        filter="url(#glow-purple)"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 2, delay: 1.2 }}
      />

      {/* Circuit Nodes - Green */}
      {[
        { cx: 1080, cy: 70 },
        { cx: 980, cy: 50 },
        { cx: 880, cy: 70 },
        { cx: 170, cy: 830 },
        { cx: 270, cy: 850 },
        { cx: 370, cy: 830 },
      ].map((pos, i) => (
        <motion.circle
          key={`node-g-${i}`}
          cx={pos.cx}
          cy={pos.cy}
          r="4"
          fill={strokeGreen}
          opacity="0.5"
          filter="url(#glow-green)"
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: [0, 1.2, 1], opacity: 0.5 }}
          transition={{ delay: 1.5 + i * 0.2, duration: 0.5 }}
        />
      ))}

      {/* Circuit Nodes - Purple */}
      {[
        { cx: 1100, cy: 140 },
        { cx: 1000, cy: 120 },
        { cx: 900, cy: 140 },
        { cx: 1280, cy: 780 },
        { cx: 1180, cy: 800 },
        { cx: 1080, cy: 780 },
      ].map((pos, i) => (
        <motion.circle
          key={`node-p-${i}`}
          cx={pos.cx}
          cy={pos.cy}
          r="3"
          fill={strokePurple}
          opacity="0.4"
          filter="url(#glow-purple)"
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: [0, 1.2, 1], opacity: 0.4 }}
          transition={{ delay: 1.8 + i * 0.2, duration: 0.5 }}
        />
      ))}

      {/* DNA Base Pair Nodes */}
      {[150, 250, 350, 450, 550, 650, 750].map((y, i) => {
        const x1 = 200 + Math.sin((y / 300) * Math.PI) * 60;
        const x2 = 320 - Math.sin((y / 300) * Math.PI) * 60;
        return (
          <g key={`dna-node-${i}`}>
            <motion.circle
              cx={x1}
              cy={y}
              r="5"
              fill={strokeGreen}
              opacity="0.6"
              filter="url(#glow-green)"
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ delay: 1.5 + i * 0.12, duration: 0.3 }}
            />
            <motion.circle
              cx={x2}
              cy={y}
              r="5"
              fill={strokePurple}
              opacity="0.6"
              filter="url(#glow-purple)"
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ delay: 1.5 + i * 0.12, duration: 0.3 }}
            />
          </g>
        );
      })}

      {/* Decorative Grid Lines */}
      {Array.from({ length: 8 }, (_, i) => (
        <line
          key={`grid-h-${i}`}
          x1="0"
          y1={i * 120 + 60}
          x2="1440"
          y2={i * 120 + 60}
          stroke={strokeDim}
          strokeWidth="0.5"
          opacity="0.3"
        />
      ))}
      {Array.from({ length: 12 }, (_, i) => (
        <line
          key={`grid-v-${i}`}
          x1={i * 120 + 60}
          y1="0"
          x2={i * 120 + 60}
          y2="900"
          stroke={strokeDim}
          strokeWidth="0.5"
          opacity="0.3"
        />
      ))}

      {/* Floating Particles */}
      {Array.from({ length: 20 }, (_, i) => {
        const x = Math.random() * 1440;
        const y = Math.random() * 900;
        const color = i % 3 === 0 ? strokePurple : strokeGreen;
        return (
          <motion.circle
            key={`particle-${i}`}
            cx={x}
            cy={y}
            r={Math.random() * 2 + 0.5}
            fill={color}
            opacity="0.3"
            animate={{
              y: [y, y - 20 - Math.random() * 30, y],
              opacity: [0.3, 0.6, 0.3],
            }}
            transition={{
              duration: 3 + Math.random() * 4,
              repeat: Infinity,
              delay: Math.random() * 2,
            }}
          />
        );
      })}
    </svg>
  );
}
