import { useState } from "react";
import { NavLink, Outlet, useLocation } from "react-router-dom";
import { MenuIcon, XIcon, DnaIcon, FlaskConicalIcon } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

const navItems = [
  { path: "/", label: "Home" },
  { path: "/blog", label: "Lab Log" },
  { path: "/metrics", label: "Metrics" },
  { path: "/tools", label: "Tools" },
  { path: "/about", label: "About" },
];

export function Layout() {
  const [mobileOpen, setMobileOpen] = useState(false);
  const location = useLocation();

  const closeMobile = () => setMobileOpen(false);

  return (
    <div className="min-h-screen bg-[#0D0D0D] text-[#E8E8E8] font-mono relative overflow-x-hidden">
      {/* Scanline texture overlay */}
      <div
        className="pointer-events-none fixed inset-0 z-50 opacity-[0.03]"
        style={{
          background:
            "repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,255,136,0.15) 2px, rgba(0,255,136,0.15) 4px)",
        }}
      />

      {/* Header */}
      <header className="fixed top-0 left-0 right-0 z-40 border-b border-[#1E1E1E] bg-[#0D0D0D]/90 backdrop-blur-md">
        <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-3 sm:px-6 lg:px-8">
          {/* Logo */}
          <NavLink
            to="/"
            className="flex items-center gap-2 text-[#00FF88]"
            onClick={closeMobile}
          >
            <DnaIcon className="h-6 w-6" />
            <span className="font-bold tracking-wider" style={{ fontFamily: "Space Grotesk, sans-serif" }}>
              biohacker<span className="text-[#7B2DFF]">.fun</span>
            </span>
          </NavLink>

          {/* Desktop Nav */}
          <nav className="hidden items-center gap-1 md:flex">
            {navItems.map((item) => (
              <NavLink
                key={item.path}
                to={item.path}
                end={item.path === "/"}
                className={({ isActive }) =>
                  `rounded-md px-3 py-2 text-sm font-medium transition-all duration-200 ${
                    isActive
                      ? "bg-[#00FF88]/10 text-[#00FF88] shadow-[0_0_8px_rgba(0,255,136,0.2)]"
                      : "text-[#888888] hover:bg-[#1E1E1E]/50 hover:text-[#E8E8E8]"
                  }`
                }
              >
                {item.label}
              </NavLink>
            ))}
          </nav>

          {/* Mobile Menu Button */}
          <button
            className="rounded-md p-2 text-[#E8E8E8] hover:bg-[#1E1E1E] md:hidden"
            onClick={() => setMobileOpen(!mobileOpen)}
            aria-label="Toggle menu"
          >
            {mobileOpen ? <XIcon className="h-6 w-6" /> : <MenuIcon className="h-6 w-6" />}
          </button>
        </div>
      </header>

      {/* Mobile Menu */}
      <AnimatePresence>
        {mobileOpen && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
            className="fixed inset-x-0 top-[57px] z-30 border-b border-[#1E1E1E] bg-[#0D0D0D]/95 backdrop-blur-md md:hidden"
          >
            <nav className="flex flex-col gap-1 px-4 py-3">
              {navItems.map((item) => (
                <NavLink
                  key={item.path}
                  to={item.path}
                  end={item.path === "/"}
                  onClick={closeMobile}
                  className={({ isActive }) =>
                    `rounded-md px-3 py-3 text-sm font-medium transition-all ${
                      isActive
                        ? "bg-[#00FF88]/10 text-[#00FF88]"
                        : "text-[#888888] hover:bg-[#1E1E1E]/50 hover:text-[#E8E8E8]"
                    }`
                  }
                >
                  {item.label}
                </NavLink>
              ))}
            </nav>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Main Content */}
      <main className="min-h-screen pt-[57px]">
        <Outlet />
      </main>

      {/* Footer */}
      <footer className="border-t border-[#1E1E1E] bg-[#0D0D0D]">
        <div className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8">
          <div className="flex flex-col items-center justify-between gap-3 text-xs text-[#888888] sm:flex-row">
            <div className="flex items-center gap-2">
              <FlaskConicalIcon className="h-4 w-4 text-[#7B2DFF]" />
              <span>biohacker.fun — DIY Biotech Lab</span>
            </div>
            <span>© {new Date().getFullYear()} All experiments reserved.</span>
          </div>
        </div>
      </footer>
    </div>
  );
}
