import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { useParams, useNavigate } from "react-router-dom";
import { ArrowLeftIcon, CalendarIcon, TagIcon, ClockIcon, SearchIcon, MessageSquareIcon } from "lucide-react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import blogPosts from "@shared/static/data/blog-posts.json";
import GiscusComments from "./components/giscus-comments";

interface IBlogPost {
  id: string;
  title: string;
  summary: string;
  content: string;
  date: string;
  category: string;
  tags: string[];
  readTime: string;
  author: string;
}

const categories = ["全部", "基因编辑", "生物传感器", "量化自我", "合成生物", "实验记录"];

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.08 },
  },
};

const itemVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.4 } },
};

function BlogList({ posts, selectedCategory, onCategoryChange }: { posts: IBlogPost[]; selectedCategory: string; onCategoryChange: (cat: string) => void }) {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState("");

  const filteredPosts = posts.filter((post) => {
    const matchCategory = selectedCategory === "全部" || post.category === selectedCategory;
    const matchSearch = post.title.toLowerCase().includes(searchQuery.toLowerCase()) || post.tags.some((tag) => tag.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchCategory && matchSearch;
  });

  return (
    <motion.div variants={containerVariants} initial="hidden" animate="visible" className="space-y-8">
      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div className="relative flex-1 max-w-md">
          <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#888888]" />
          <input
            type="text"
            placeholder="搜索文章或标签..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-[#141414] border border-[#1E1E1E] text-[#E8E8E8] rounded-md focus:border-[#00FF88] focus:ring-1 focus:ring-[#00FF88] placeholder:text-[#888888]"
          />
        </div>
      </div>

      <div className="flex flex-wrap gap-2">
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => onCategoryChange(cat)}
            className={`px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 ${
              selectedCategory === cat
                ? "bg-[#00FF88] text-[#0D0D0D]"
                : "border border-[#1E1E1E] text-[#888888] hover:border-[#00FF88]/50 hover:text-[#00FF88]"
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {filteredPosts.map((post) => (
          <motion.article
            key={post.id}
            variants={itemVariants}
            onClick={() => navigate(`/blog/${post.id}`)}
            className="group cursor-pointer rounded-lg border border-[#1E1E1E] bg-[#141414] p-6 transition-all duration-300 hover:border-[#00FF88]/50 hover:shadow-[0_0_15px_rgba(0,255,136,0.15)]"
          >
            <div className="flex items-center gap-2 text-xs text-[#888888] mb-3">
              <CalendarIcon className="w-3 h-3" />
              <span>{post.date}</span>
              <ClockIcon className="w-3 h-3 ml-2" />
              <span>{post.readTime}</span>
            </div>
            <h3 className="text-lg font-bold text-[#E8E8E8] mb-2 group-hover:text-[#00FF88] transition-colors">{post.title}</h3>
            <p className="text-sm text-[#888888] mb-4 line-clamp-2">{post.summary}</p>
            <div className="flex flex-wrap gap-2">
              {post.tags.slice(0, 3).map((tag) => (
                <span key={tag} className="border border-[#FF3366] text-[#FF3366] px-2 py-0.5 rounded text-xs">
                  {tag}
                </span>
              ))}
            </div>
          </motion.article>
        ))}
      </div>

      {filteredPosts.length === 0 && (
        <div className="text-center py-16 text-[#888888]">
          <SearchIcon className="w-12 h-12 mx-auto mb-4 opacity-50" />
          <p>没有找到匹配的文章</p>
        </div>
      )}
    </motion.div>
  );
}

function BlogDetail({ post }: { post: IBlogPost }) {
  const navigate = useNavigate();

  return (
    <motion.article initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }} className="max-w-3xl mx-auto">
      <button
        onClick={() => navigate("/blog")}
        className="flex items-center gap-2 text-[#888888] hover:text-[#00FF88] transition-colors mb-8"
      >
        <ArrowLeftIcon className="w-4 h-4" />
        <span>返回文章列表</span>
      </button>

      <div className="flex items-center gap-2 text-xs text-[#888888] mb-4">
        <CalendarIcon className="w-3 h-3" />
        <span>{post.date}</span>
        <ClockIcon className="w-3 h-3 ml-2" />
        <span>{post.readTime}</span>
        <TagIcon className="w-3 h-3 ml-2" />
        <span>{post.category}</span>
      </div>

      <h1 className="text-3xl md:text-4xl font-bold text-[#E8E8E8] mb-6">{post.title}</h1>

      <div className="flex flex-wrap gap-2 mb-8">
        {post.tags.map((tag) => (
          <span key={tag} className="border border-[#FF3366] text-[#FF3366] px-2 py-0.5 rounded text-xs">
            {tag}
          </span>
        ))}
      </div>

      <div className="prose prose-invert max-w-none prose-headings:text-[#00FF88] prose-a:text-[#00FF88] prose-code:bg-[#141414] prose-code:text-[#00FF88] prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded prose-pre:bg-[#141414] prose-pre:border prose-pre:border-[#1E1E1E]">
        <ReactMarkdown remarkPlugins={[remarkGfm]}>{post.content}</ReactMarkdown>
      </div>

      <div className="mt-12 pt-8 border-t border-[#1E1E1E]">
        <div className="flex items-center gap-2 mb-6 text-[#00FF88]">
          <MessageSquareIcon className="w-5 h-5" />
          <h3 className="text-lg font-bold">评论</h3>
        </div>
        <GiscusComments />
      </div>
    </motion.article>
  );
}

export default function BlogPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [selectedCategory, setSelectedCategory] = useState("全部");
  const [posts, setPosts] = useState<IBlogPost[]>([]);

  useEffect(() => {
    setPosts(blogPosts as unknown as IBlogPost[]);
  }, []);

  const currentPost = id ? posts.find((p) => p.id === id) : null;

  return (
    <div className="min-h-full bg-[#0D0D0D] py-12 px-4 md:px-8">
      <div className="max-w-6xl mx-auto">
        {!id ? (
          <>
            <motion.h1 initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} className="text-3xl md:text-4xl font-bold text-[#E8E8E8] mb-2">
              实验日志
            </motion.h1>
            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.2 }} className="text-[#888888] mb-10">
              记录生物黑客实验、量化自我数据与合成生物学探索
            </motion.p>
            <BlogList posts={posts} selectedCategory={selectedCategory} onCategoryChange={setSelectedCategory} />
          </>
        ) : currentPost ? (
          <BlogDetail post={currentPost} />
        ) : (
          <div className="text-center py-16 text-[#888888]">
            <p className="text-xl mb-4">文章未找到</p>
            <button onClick={() => navigate("/blog")} className="text-[#00FF88] hover:underline">
              返回文章列表
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
